const sleep=ms=>new Promise(r=>setTimeout(r,ms));
const IDS=["24835692","28943009","27522980","38702964","35494495","33472488","32771464","17826254","27565607","42169800"];
(async()=>{
 for(let i=0;i<IDS.length;i+=4){
  const chunk=IDS.slice(i,i+4);
  const t=await get('https://eutils.ncbi.nlm.nih.gov/entrez/eutils/efetch.fcgi?db=pubmed&rettype=abstract&retmode=text&id='+chunk.join(','));
  t.split(/\n\n(?=\d+\.\s)/).forEach(rec=>{
    let c=rec.replace(/\s+/g,' ').trim();
    // strip author-affiliation noise
    c=c.replace(/Author information:.*?(?=(OBJECTIVE|BACKGROUND|PURPOSE|METHODS|INTRODUCTION|CONTEXT|Thoracic outlet|Neurogenic|[A-Z]{4,}:))/,' ||AFFIL-STRIPPED|| ');
    console.log('---\n'+c.slice(0,2600)+'\n');
  });
  await sleep(400);
 }
})();

```

